{
  "apiVersion": "diorama.io/v1alpha1",
  "kind": "Config",
  "path": "/srv/fixture",
  "api": {
    "enabled": true,
    "socketPath": "/run/fixture.sock"
  },
  "logging": {
    "debug": true,
    "pprof": true
  },
  "network": {
    "nodeIP": "192.0.2.10",
    "mtu": 1400,
    "disableIPv6": true,
    "loadBalancer": {
      "enabled": true,
      "ip": "192.0.2.20"
    }
  },
  "runtime": {
    "endpoint": "unix:///run/crio/crio.sock",
    "containerMode": false
  },
  "kubernetes": {
    "nodeName": "fixture-node",
    "apiServer": {
      "extraSANs": [
        "example.invalid",
        "192.0.2.11"
      ],
      "startupTimeoutSeconds": 123
    },
    "kubelet": {
      "cpuManager": {
        "policy": "none"
      },
      "systemReserved": {
        "memory": "128Mi"
      }
    }
  },
  "storage": {
    "localPath": {
      "enabled": false,
      "sharedPath": "/srv/volumes"
    },
    "dbWALRepair": true
  },
  "portainer": {
    "edgeID": "fixture-id",
    "edgeKey": "synthetic-fixture-key",
    "async": true,
    "image": "portainer/agent:fixture"
  },
  "d2k": {
    "enabled": true,
    "namespace": "fixture-d2k"
  },
  "metrics": {
    "enabled": true,
    "bindAddress": "127.0.0.1:9205"
  }
}
